<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require_admin($pdo);
$daily=$pdo->query("SELECT DATE(created_at) day,COUNT(*) orders,SUM(total) sales FROM customer_orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 29 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();
$top=$pdo->query("SELECT i.item_name,SUM(i.quantity) units,SUM(i.line_total) revenue FROM customer_order_items i JOIN customer_orders o ON o.order_id=i.order_id WHERE o.created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND LOWER(o.status)<>'cancelled' GROUP BY i.item_name ORDER BY units DESC LIMIT 10")->fetchAll();
$hasUnitCost=false;
try { $pdo->query('SELECT unit_cost FROM menu_items LIMIT 0'); $hasUnitCost=true; } catch(PDOException $e) { /* Cost reporting is optional until its migration is applied. */ }
$marginRows=[]; $marginSummary=['gross_profit'=>null];
if($hasUnitCost){
    $marginRows=$pdo->query("SELECT i.item_name,SUM(i.quantity) units,SUM(i.line_total) revenue,SUM(i.quantity*m.unit_cost) cost,SUM(i.line_total-i.quantity*m.unit_cost) gross_profit FROM customer_order_items i JOIN customer_orders o ON o.order_id=i.order_id JOIN menu_items m ON m.item_id=i.item_id WHERE o.created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND LOWER(o.status) NOT IN ('cancelled','rejected','failed') AND m.unit_cost IS NOT NULL GROUP BY i.item_name ORDER BY gross_profit DESC LIMIT 10")->fetchAll();
    $marginSummary=$pdo->query("SELECT SUM(i.line_total) revenue,SUM(i.quantity*m.unit_cost) cost,SUM(i.line_total-i.quantity*m.unit_cost) gross_profit FROM customer_order_items i JOIN customer_orders o ON o.order_id=i.order_id JOIN menu_items m ON m.item_id=i.item_id WHERE o.created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND LOWER(o.status) NOT IN ('cancelled','rejected','failed') AND m.unit_cost IS NOT NULL")->fetch();
}
$summary=$pdo->query("SELECT COUNT(*) orders,COALESCE(SUM(total),0) sales,COALESCE(AVG(total),0) average FROM customer_orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND LOWER(status)<>'cancelled'")->fetch();
$branchSales=$pdo->query("SELECT COALESCE(NULLIF(branch_id,''),'Unassigned') branch_id,COUNT(*) orders,COALESCE(SUM(total),0) sales FROM customer_orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND LOWER(status) NOT IN ('cancelled','rejected','failed') GROUP BY branch_id ORDER BY sales DESC")->fetchAll();
$customerRepeat=$pdo->query("SELECT COUNT(*) customers,COALESCE(SUM(order_count>=2),0) repeat_customers FROM (SELECT user_id,COUNT(*) order_count FROM customer_orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND user_id IS NOT NULL AND LOWER(status) NOT IN ('cancelled','rejected','failed') GROUP BY user_id) c")->fetch();
$orderGap=$pdo->query("SELECT AVG(gap_minutes) avg_minutes FROM (SELECT TIMESTAMPDIFF(MINUTE,(SELECT MAX(prev.created_at) FROM customer_orders prev WHERE prev.user_id=o.user_id AND prev.created_at<o.created_at AND prev.created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND LOWER(prev.status) NOT IN ('cancelled','rejected','failed')),o.created_at) gap_minutes FROM customer_orders o WHERE o.created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND o.user_id IS NOT NULL AND LOWER(o.status) NOT IN ('cancelled','rejected','failed')) gaps WHERE gap_minutes IS NOT NULL")->fetch();
$cancellation=$pdo->query("SELECT COUNT(*) total_orders,COALESCE(SUM(LOWER(status)='cancelled'),0) cancelled FROM customer_orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY)")->fetch();
$prep=$pdo->query("SELECT AVG(TIMESTAMPDIFF(MINUTE,p.started_at,f.finished_at)) avg_minutes,COUNT(*) completed_orders FROM (SELECT order_id,MIN(created_at) started_at FROM staff_order_actions WHERE to_status='preparing' GROUP BY order_id) p JOIN (SELECT order_id,MIN(created_at) finished_at FROM staff_order_actions WHERE to_status IN ('ready','out_for_delivery','completed') GROUP BY order_id) f ON f.order_id=p.order_id WHERE f.finished_at>=p.started_at AND f.finished_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetch();
$repeatRate=(int)$customerRepeat['customers']>0?100*(int)$customerRepeat['repeat_customers']/(int)$customerRepeat['customers']:0;
$cancelRate=(int)$cancellation['total_orders']>0?100*(int)$cancellation['cancelled']/(int)$cancellation['total_orders']:0;
$branchNames=[]; foreach(json_decode((string)file_get_contents(__DIR__.'/assets/branches-data.json'),true)?:[] as $branchInfo)$branchNames[(string)$branchInfo['id']]=(string)$branchInfo['name'];
$pageTitle='Sales analytics'; $pageScripts='<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const salesData='.json_encode($daily,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP).';new Chart(document.getElementById("salesChart"),{type:"line",data:{labels:salesData.map(x=>x.day),datasets:[{label:"Sales (₱)",data:salesData.map(x=>Number(x.sales)),borderColor:"#8b3f24",backgroundColor:"rgba(139,63,36,.12)",fill:true,tension:.3},{label:"Orders",data:salesData.map(x=>Number(x.orders)),borderColor:"#3e7662",yAxisID:"y1",tension:.3}]},options:{responsive:true,interaction:{mode:"index",intersect:false},scales:{y:{beginAtZero:true},y1:{position:"right",beginAtZero:true,grid:{drawOnChartArea:false}}}}});</script>';
require 'includes/header.php'; ?>
<main class="container py-5"><div class="mb-4"><p class="text-uppercase small fw-semibold text-secondary mb-1">Admin</p><h1>Sales analytics</h1><p class="text-secondary">Order performance for the last 30 days. Cancelled orders are excluded from sales and best sellers.</p></div><div class="row g-3 mb-4"><?php foreach([['Sales','₱'.number_format((float)$summary['sales'],2)],['Orders',(int)$summary['orders']],['Average order','₱'.number_format((float)$summary['average'],2)],['Repeat customer rate',number_format($repeatRate,1).'%'],['Cancellation rate',number_format($cancelRate,1).'%'],['Avg. prep time',$prep['avg_minutes']!==null?number_format((float)$prep['avg_minutes'],1).' min':'—'],['Avg. time between orders',$orderGap['avg_minutes']!==null?number_format((float)$orderGap['avg_minutes']/60,1).' hrs':'—'],['Gross profit',is_numeric($marginSummary['gross_profit'])?'₱'.number_format((float)$marginSummary['gross_profit'],2):'Add item costs']] as [$label,$value]): ?><div class="col-6 col-lg-4"><section class="card card-body h-100"><div class="text-secondary"><?=$label?></div><div class="fs-3 fw-semibold"><?=$value?></div></section></div><?php endforeach; ?></div><section class="card card-body mb-4"><h2 class="h4">Daily sales and orders</h2><canvas id="salesChart" height="95" aria-label="Sales and order counts over the last 30 days"></canvas></section><div class="row g-4 mb-4"><div class="col-lg-6"><section class="card card-body h-100"><h2 class="h4">Best sellers</h2><p class="small text-secondary">Ranked by units sold. Item revenue uses line totals, including selected upgrades.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Menu item</th><th>Units</th><th>Revenue</th></tr></thead><tbody><?php foreach($top as $item): ?><tr><td><?=e($item['item_name'])?></td><td><?=number_format((int)$item['units'])?></td><td>₱<?=number_format((float)$item['revenue'],2)?></td></tr><?php endforeach; ?><?php if(!$top): ?><tr><td colspan="3" class="text-secondary">No order item sales yet.</td></tr><?php endif; ?></tbody></table></div></section></div><div class="col-lg-6"><section class="card card-body h-100"><h2 class="h4">Sales by branch</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Branch</th><th>Orders</th><th>Sales</th></tr></thead><tbody><?php foreach($branchSales as $branch): ?><tr><td><?=e($branchNames[(string)$branch['branch_id']]??$branch['branch_id'])?></td><td><?=number_format((int)$branch['orders'])?></td><td>₱<?=number_format((float)$branch['sales'],2)?></td></tr><?php endforeach; ?><?php if(!$branchSales): ?><tr><td colspan="3" class="text-secondary">No branch sales in this period.</td></tr><?php endif; ?></tbody></table></div></section></div></div><section class="card card-body mb-4"><h2 class="h4">Gross margin by item</h2><p class="small text-secondary">Estimated using each menu entry’s current unit cost and historical sold quantities. Selected option costs are not included.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Menu item</th><th>Revenue</th><th>Cost</th><th>Gross profit</th><th>Margin</th></tr></thead><tbody><?php foreach($marginRows as $item): $marginPercent=(float)$item['revenue']>0?100*(float)$item['gross_profit']/(float)$item['revenue']:0; ?><tr><td><?=e($item['item_name'])?></td><td>₱<?=number_format((float)$item['revenue'],2)?></td><td>₱<?=number_format((float)$item['cost'],2)?></td><td>₱<?=number_format((float)$item['gross_profit'],2)?></td><td><?=number_format($marginPercent,1)?>%</td></tr><?php endforeach; ?><?php if(!$marginRows): ?><tr><td colspan="5" class="text-secondary">Add unit costs to menu entries to see gross margin reports.</td></tr><?php endif; ?></tbody></table></div></section><section class="card card-body"><h2 class="h4">Report definitions</h2><ul class="mb-0"><li>Repeat customer rate counts registered customers with two or more non-cancelled orders in the period.</li><li>Average time between orders uses gaps between registered customer orders in the 30-day period.</li><li>Average prep time uses recorded order transitions from “preparing” to “ready”, “out for delivery”, or “completed”.</li><li>Gross margin uses current unit cost for sold menu items; selected option costs are not included yet.</li></ul></section></main><?php require 'includes/footer.php'; ?>
